/* eslint-disable @typescript-eslint/no-explicit-any */
/**
 * @file challenger2_public_features_integrity.test.tsx
 * @description Empirical Challenger 2 Verification Suite:
 * Core Public Feature Integrity Verification (Admin, Lounge, and Auth Purge)
 *
 * Requirements:
 * 1. Verify Apartment details, 18-year real transactions, Macro trends, Techno Valley, and MBTI work 100% publicly without login.
 * 2. Verify useFavorites operates 100% locally via localStorage without network calls to /api/favorite.
 * 3. Verify AuthProvider wraps the tree without initiating any Firebase Auth network listeners.
 * 4. Verify zero runtime exceptions or authentication gate blocks across all public flows.
 */

import React from 'react';
import { render, screen, act, fireEvent, renderHook } from '@testing-library/react';
import '@testing-library/jest-dom';

// ---------------------------------------------------------------------------
// Mocks & Polyfills
// ---------------------------------------------------------------------------

window.scrollTo = jest.fn();

const mockRedirect = jest.fn();
jest.mock('next/navigation', () => ({
  useRouter: () => ({
    push: jest.fn(),
    replace: jest.fn(),
    back: jest.fn(),
    prefetch: jest.fn(),
  }),
  usePathname: () => '/',
  useSearchParams: () => new URLSearchParams(),
  redirect: (url: string) => mockRedirect(url),
}));

// Recharts mock for jsdom
jest.mock('recharts', () => {
  const Original = jest.requireActual('recharts');
  return {
    ...Original,
    ResponsiveContainer: ({ children }: any) => <div data-testid="responsive-container">{children}</div>,
    PieChart: ({ children }: any) => <svg data-testid="pie-chart">{children}</svg>,
    Pie: ({ children }: any) => <g data-testid="pie">{children}</g>,
    Cell: () => <path data-testid="pie-cell" />,
    LineChart: ({ children }: any) => <svg data-testid="line-chart">{children}</svg>,
    Line: () => <path data-testid="line" />,
    XAxis: () => <g data-testid="x-axis" />,
    YAxis: () => <g data-testid="y-axis" />,
    CartesianGrid: () => <g data-testid="cartesian-grid" />,
    Tooltip: () => <div data-testid="tooltip" />,
  };
});

// Mock react-intersection-observer
jest.mock('react-intersection-observer', () => ({
  useInView: () => ({
    ref: jest.fn(),
    inView: true,
  }),
}));

// Mock apartment repository to prevent background unawaited logs
jest.mock('@/lib/repositories/apartment.repository', () => ({
  fetchApartmentNames: jest.fn().mockResolvedValue([]),
  fetchApartmentMeta: jest.fn().mockResolvedValue({}),
}));

// Mock SWR to avoid background timers
jest.mock('swr', () => {
  const original = jest.requireActual('swr');
  return {
    __esModule: true,
    ...original,
    default: jest.fn((url: string) => {
      if (typeof url === 'string' && url.includes('industry-distribution')) {
        return { data: { distribution: [] }, isValidating: false, isLoading: false };
      }
      if (typeof url === 'string' && url.includes('trend')) {
        return { data: { trends: [] }, isValidating: false, isLoading: false };
      }
      return { data: undefined, isValidating: false, isLoading: false };
    }),
    preload: jest.fn(),
  };
});

// Import tested components & modules
import { AuthProvider, useAuth, STATIC_AUTH_STATE } from '@/contexts/AuthContext';
import { useAuth as useLibAuth } from '@/lib/contexts/AuthContext';
import { SettingsProvider } from '@/contexts/SettingsContext';
import { useFavorites } from '@/hooks/useFavorites';
import { staticDataService, parsePeriodTransactions } from '@/lib/services/staticDataService';
import ApartmentModal from '@/components/apartment/ApartmentModal';
import MacroDashboardClient from '@/components/MacroDashboardClient';
import { MacroTimelineView, TimelineGroup } from '@/components/macro/components/MacroTimelineView';
import TechnoValleyPage from '@/app/technovalley/page';
import TechnoValleyClient from '@/app/technovalley/TechnoValleyClient';
import { MBTIContainer } from '@/components/mbti/MBTIContainer';
import type { FieldReportData } from '@/lib/DashboardFacade';
import type { RecentTransaction } from '@/types/transaction';
import type { User } from 'firebase/auth';

describe('Challenger 2: Core Public Feature Integrity & Zero-Auth Verification', () => {
  const originalFetch = global.fetch;
  let fetchSpy: jest.Mock;

  beforeEach(() => {
    localStorage.clear();
    jest.clearAllMocks();
    fetchSpy = jest.fn().mockImplementation((url: string) => {
      if (url.includes('/api/favorite-counts')) {
        return Promise.resolve(new Response(JSON.stringify({ counts: {} }), { status: 200 }));
      }
      return Promise.resolve(new Response(JSON.stringify({}), { status: 200 }));
    });
    global.fetch = fetchSpy;
  });

  afterAll(() => {
    global.fetch = originalFetch;
  });

  // =========================================================================
  // Dimension 1: Auth Neutralization & Tree Wrapping
  // =========================================================================
  describe('Dimension 1: Auth Neutralization & Static Anonymous State', () => {
    it('AuthProvider wraps children without initiating any Firebase Auth listeners', () => {
      const ChildComponent = () => {
        const auth = useAuth();
        return (
          <div data-testid="auth-consumer">
            <span data-testid="auth-user">{auth.user ? 'logged_in' : 'anonymous'}</span>
            <span data-testid="auth-loading">{String(auth.isLoading)}</span>
          </div>
        );
      };

      render(
        <AuthProvider>
          <ChildComponent />
        </AuthProvider>
      );

      expect(screen.getByTestId('auth-user')).toHaveTextContent('anonymous');
      expect(screen.getByTestId('auth-loading')).toHaveTextContent('false');
    });

    it('useAuth provides immutable STATIC_AUTH_STATE with no-op handlers', async () => {
      const { result } = renderHook(() => useAuth());

      expect(result.current.user).toBeNull();
      expect(result.current.userProfile).toBeNull();
      expect(result.current.anonProfile).toBeNull();
      expect(result.current.isLoading).toBe(false);

      // Verify handlers complete cleanly without errors
      await expect(result.current.handleLogin()).resolves.toBeUndefined();
      await expect(result.current.handleLogout()).resolves.toBeUndefined();
      expect(() => result.current.updateLocalAnonProfile({ nickname: 'test' })).not.toThrow();
    });

    it('lib/contexts/AuthContext re-exports identical symbols for backward compatibility', () => {
      const { result: mainResult } = renderHook(() => useAuth());
      const { result: libResult } = renderHook(() => useLibAuth());

      expect(libResult.current.user).toBe(mainResult.current.user);
      expect(libResult.current.isLoading).toBe(mainResult.current.isLoading);
      expect(STATIC_AUTH_STATE.user).toBeNull();
    });
  });

  // =========================================================================
  // Dimension 2: useFavorites 100% Local Storage & Zero Network /api/favorite Calls
  // =========================================================================
  describe('Dimension 2: useFavorites Local Storage & Zero Remote Calls', () => {
    it('operates 100% locally via localStorage and CustomEvents without remote calls to /api/favorite', async () => {
      localStorage.setItem('dview_guest_favorites', JSON.stringify(['동탄역 롯데캐슬']));
      const dispatchSpy = jest.spyOn(window, 'dispatchEvent');

      const { result } = renderHook(() => useFavorites(null, { '동탄역 롯데캐슬': 15 }));

      // Verify initial state read from localStorage
      expect(result.current.isFavorited('동탄역 롯데캐슬')).toBe(true);
      expect(result.current.isFavorited('동탄역 시범우남퍼스트빌')).toBe(false);
      expect(result.current.favoritesCount).toBe(1);

      // Add a favorite
      await act(async () => {
        await result.current.handleToggleFavorite('동탄역 시범우남퍼스트빌');
      });

      expect(result.current.isFavorited('동탄역 시범우남퍼스트빌')).toBe(true);
      expect(result.current.favoritesCount).toBe(2);
      expect(dispatchSpy).toHaveBeenCalledWith(
        expect.objectContaining({ type: 'dview_favorites_updated' })
      );

      // Verify localStorage was updated
      const stored = JSON.parse(localStorage.getItem('dview_guest_favorites') || '[]');
      expect(stored).toContain('동탄역 시범우남퍼스트빌');
      expect(stored).toContain('동탄역 롯데캐슬');

      // Verify ZERO calls were made to /api/favorite
      const calledUrls = fetchSpy.mock.calls.map((c: any[]) => c[0]);
      const favoriteApiCalls = calledUrls.filter((url: string) =>
        url === '/api/favorite' || url.startsWith('/api/favorite?') || url === '/api/favorites'
      );
      expect(favoriteApiCalls).toHaveLength(0);
    });

    it('operates 100% locally even when a legacy user object is passed into useFavorites', async () => {
      const legacyMockUser = { uid: 'user_456' } as unknown as User;
      localStorage.setItem('dview_guest_favorites', JSON.stringify(['동탄역 롯데캐슬']));

      const { result } = renderHook(() => useFavorites(legacyMockUser));

      // Remove favorite
      await act(async () => {
        await result.current.handleToggleFavorite('동탄역 롯데캐슬');
      });

      expect(result.current.isFavorited('동탄역 롯데캐슬')).toBe(false);
      expect(result.current.favoritesCount).toBe(0);

      // Verify zero network calls to /api/favorite
      const calledUrls = fetchSpy.mock.calls.map((c: any[]) => c[0]);
      const favoriteApiCalls = calledUrls.filter((url: string) =>
        url === '/api/favorite' || url.startsWith('/api/favorite?')
      );
      expect(favoriteApiCalls).toHaveLength(0);
    });
  });

  // =========================================================================
  // Dimension 3: Apartment Details & Modal (100% Public Access)
  // =========================================================================
  describe('Dimension 3: Apartment Details & Modal (100% Public)', () => {
    const sampleReport: FieldReportData = {
      id: 'apt-lotte-castle',
      apartmentName: '동탄역 롯데캐슬',
      dong: '오산동',
      householdCount: 940,
      completionDate: '2021-06',
      brand: '롯데캐슬',
      summary: '동탄역 초역세권 대표 대장 아파트 단지',
      metrics: {
        elementarySchool: '청계초',
        middleSchool: '청계중',
        highSchool: '동탄고',
        kindergartenCount: 5,
        academyCount: 42,
        busStopCount: 6,
        subwayDistanceKm: 0.1,
        parkDistanceKm: 0.3,
        householdCount: 940,
      } as any,
      images: [],
    };

    const sampleTransactions = [
      {
        dong: '오산동',
        aptName: '동탄역 롯데캐슬',
        area: 84.9,
        areaPyeong: 34,
        contractYm: '202603',
        contractDay: '15',
        price: 165000,
        priceEok: '16억5,000',
        floor: 25,
        buildYear: 2021,
        dealType: '매매',
      },
      {
        dong: '오산동',
        aptName: '동탄역 롯데캐슬',
        area: 84.9,
        areaPyeong: 34,
        contractYm: '202602',
        contractDay: '10',
        price: 80000,
        deposit: 80000,
        priceEok: '8억',
        floor: 18,
        buildYear: 2021,
        dealType: '전세',
      },
    ];

    it('renders ApartmentModal with full public details, metrics, and transactions without login', () => {
      const handleClose = jest.fn();

      render(
        <SettingsProvider>
          <AuthProvider>
            <ApartmentModal
              report={sampleReport}
              onClose={handleClose}
              user={null}
              transactions={sampleTransactions as any}
              typeMap={{}}
              inline={true}
            />
          </AuthProvider>
        </SettingsProvider>
      );

      // Verify title renders cleanly
      expect(screen.getAllByText('동탄역 롯데캐슬').length).toBeGreaterThanOrEqual(1);
      expect(screen.getAllByText('오산동').length).toBeGreaterThanOrEqual(1);

      // Verify public action buttons exist
      expect(screen.getByTitle('아파트 분석 리포트 공유하기')).toBeInTheDocument();
      expect(screen.getByTitle('단톡방용 텍스트 요약 복사')).toBeInTheDocument();
      expect(screen.getByTitle('인포그래픽 요약 카드 이미지 다운로드')).toBeInTheDocument();

      // Verify no login buttons or prompts exist
      expect(screen.queryByText(/로그인하고 계속하기/i)).not.toBeInTheDocument();
      expect(screen.queryByText(/로그인이 필요합니다/i)).not.toBeInTheDocument();
    });

    it('does not render favorite button in ApartmentModal after favorites feature removal', () => {
      render(
        <SettingsProvider>
          <AuthProvider>
            <ApartmentModal
              report={sampleReport}
              onClose={jest.fn()}
              user={null}
              transactions={sampleTransactions as any}
              typeMap={{}}
              inline={true}
            />
          </AuthProvider>
        </SettingsProvider>
      );

      const favButton = screen.queryByLabelText(/관심 단지/i);
      expect(favButton).not.toBeInTheDocument();
    });
  });

  // =========================================================================
  // Dimension 4: 18-Year Real Transactions & Period Chunks (100% Public)
  // =========================================================================
  describe('Dimension 4: 18-Year Real Transactions & Period Chunks', () => {
    it('parsePeriodTransactions parses compact tuple JSON format accurately', () => {
      const compactPayload = {
        fields: ['aptName', 'txKey', 'date', 'contractDate', 'priceVal', 'priceEok', 'area', 'areaPyeong', 'floor', 'dealType'],
        data: [
          ['동탄역 롯데캐슬', '동탄역롯데캐슬', '26.03', '20260315', 16.5, '16억5,000', 84.9, 34, 25, '매매'],
          ['동탄역시범우남퍼스트빌', '동탄역시범우남퍼스트빌', '26.02', '20260220', 11.2, '11억2,000', 84.8, 34, 15, '매매'],
        ],
      };

      const parsed = parsePeriodTransactions(compactPayload);
      expect(parsed).toHaveLength(2);
      expect(parsed[0].aptName).toBe('동탄역 롯데캐슬');
      expect(parsed[0].priceVal).toBe(16.5);
      expect(parsed[0].priceEok).toBe('16억5,000');
      expect(parsed[1].aptName).toBe('동탄역시범우남퍼스트빌');
    });

    it('fetchPeriodTransactions requests versioned CDN JSON chunks without Firestore reads', async () => {
      const mockPeriodTxs: RecentTransaction[] = [
        {
          aptName: '동탄역 롯데캐슬',
          txKey: '동탄역롯데캐슬',
          date: '26.03',
          contractDate: '20260315',
          priceVal: 16.5,
          priceEok: '16억5,000',
          area: 84.9,
          areaPyeong: 34,
          floor: 25,
          dealType: '매매',
        },
      ];

      fetchSpy.mockResolvedValueOnce(
        new Response(JSON.stringify(mockPeriodTxs), { status: 200 })
      );

      const data = await staticDataService.fetchPeriodTransactions('1y', 'v_test_123');
      expect(data).toHaveLength(1);
      expect(data[0].aptName).toBe('동탄역 롯데캐슬');

      // Verify exact CDN path requested
      expect(fetchSpy).toHaveBeenCalledWith(
        '/data/transactions-1y.json?v=v_test_123',
        expect.anything()
      );
    });

    it('staticDataService returns [] and 0 Firestore reads in browser runtime', async () => {
      expect(typeof window).not.toBe('undefined');
      const firestoreTxs = await staticDataService.fetchRecentTransactionsFromFirestore(30);
      expect(firestoreTxs).toEqual([]);
    });

    it('renders MacroTimelineView with multi-period transaction groups and handles filter toggles', () => {
      const timelineData: TimelineGroup[] = [
        {
          dateStr: '2026.03.15',
          timestamp: 1773532800000,
          items: [
            {
              aptName: '동탄역 롯데캐슬',
              dong: '오산동',
              priceEok: '16억5,000',
              priceVal: 16.5,
              areaPyeong: 34,
              area: 84.9,
              floor: 25,
              type: 'high',
              delta: 0.5,
              deltaPercent: 3.1,
            },
          ],
        },
      ];

      const handleSelectApt = jest.fn();
      const setPeriodFilter = jest.fn();

      render(
        <SettingsProvider>
          <AuthProvider>
            <MacroTimelineView
              displayedTimelineData={timelineData}
              onSelectApt={handleSelectApt}
              periodFilter="90d"
              setPeriodFilter={setPeriodFilter}
              visibleTimelineCount={10}
            />
          </AuthProvider>
        </SettingsProvider>
      );

      expect(screen.getByText('동탄역 롯데캐슬')).toBeInTheDocument();
      expect(screen.getByText('16억5,000')).toBeInTheDocument();
      expect(screen.getByText(/오산동/)).toBeInTheDocument();
    });

    it('renders MacroDashboardClient completely publicly without authentication barriers', () => {
      const mockSheetApartments = {
        '오산동': [
          { name: '동탄역 롯데캐슬', dong: '오산동', txKey: '동탄역롯데캐슬' } as any,
        ],
      };
      const mockTxSummaryData = {
        '동탄역 롯데캐슬': {
          latestPrice: 165000,
          dong: '오산동',
          avg1MPrice: 165000,
          avg3MPrice: 162000,
        } as any,
      };

      render(
        <SettingsProvider>
          <AuthProvider>
            <MacroDashboardClient
              sheetApartments={mockSheetApartments}
              txSummaryData={mockTxSummaryData}
              macroTrendData={[]}
              publicRentalSet={new Set()}
              fieldReportsMap={new Map()}
              favoriteCounts={{}}
              recentTransactions={[]}
            />
          </AuthProvider>
        </SettingsProvider>
      );

      // Verify dashboard components render without throwing
      expect(screen.getByText('일자별 최근 실거래')).toBeInTheDocument();
      expect(screen.getByTestId('timeline-period-tab-90d')).toBeInTheDocument();
    });
  });

  // =========================================================================
  // Dimension 5: Techno Valley & MBTI (100% Public Access)
  // =========================================================================
  describe('Dimension 5: Techno Valley & MBTI Public Routing & Features', () => {
    it('TechnoValleyPage redirects cleanly to / without runtime errors', () => {
      TechnoValleyPage();
      expect(mockRedirect).toHaveBeenCalledWith('/');
    });

    it('TechnoValleyClient renders public dashboard without authentication dependency', () => {
      render(
        <SettingsProvider>
          <AuthProvider>
            <TechnoValleyClient />
          </AuthProvider>
        </SettingsProvider>
      );
      expect(screen.getAllByText('D-VIEW 테크노 랩').length).toBeGreaterThanOrEqual(1);
      expect(screen.getByText('동탄 테크노밸리 심층 데이터 분석')).toBeInTheDocument();
    });

    it('MBTIContainer renders public 1-minute housing personality quiz intro without login', () => {
      render(<MBTIContainer initialView="intro" />);

      expect(screen.getByText(/나와 영혼의 궁합인/i)).toBeInTheDocument();
      expect(screen.getByTestId('start-quiz-btn')).toBeInTheDocument();
      expect(screen.getByTestId('browse-encyclopedia-btn')).toBeInTheDocument();

      // Click Start Quiz
      fireEvent.click(screen.getByTestId('start-quiz-btn'));

      // Verify quiz view mounts
      expect(screen.getByTestId('tab-nav-quiz')).toBeInTheDocument();
      expect(screen.queryByText(/로그인이 필요합니다/i)).not.toBeInTheDocument();
    });

    it('MBTIContainer renders 16-type apartment encyclopedia publicly', () => {
      render(<MBTIContainer initialView="encyclopedia" />);

      // Verify encyclopedia view
      expect(screen.getByTestId('tab-nav-encyclopedia')).toBeInTheDocument();
      expect(screen.getByText(/16개 아파트 도감/i)).toBeInTheDocument();
    });
  });
});

import React, { useState, useEffect, useMemo, useRef } from "react";
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip as RechartsTooltip,
  CartesianGrid,
  ReferenceArea,
  ReferenceLine,
} from "recharts";
import type { DongtanMacroTrendPoint } from "@/lib/types/transaction";
import { processMacroTrendData, formatXAxisTick } from "@/lib/utils/macroChartTransform";
import ChartErrorBoundary from "@/components/common/ChartErrorBoundary";
import { calculateTwoSigma, type TwoSigmaStats } from "@/lib/analytics/twoSigmaEngine";

const SafeReferenceArea = ReferenceArea as React.ComponentType<
  React.ComponentProps<typeof ReferenceArea> & { isFront?: boolean }
>;

interface TooltipPayloadEntry {
  dataKey?: string | number;
  name?: string;
  value: number;
  color?: string;
  payload?: unknown;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: TooltipPayloadEntry[];
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    const saleData = payload.find(
      (p) => p.dataKey === "동탄 아파트 전체" || p.name === "평균 매매가"
    );
    const rentData = payload.find(
      (p) =>
        p.dataKey === "동탄 아파트 전세 평균" || p.name === "평균 전세가"
    );

    const salePrice = saleData?.value || 0;
    const rentPrice = rentData?.value || 0;

    let ratio = 0;
    if (salePrice > 0 && rentPrice > 0) {
      ratio = (rentPrice / salePrice) * 100;
    }

    const gapPrice = salePrice > 0 && rentPrice > 0 ? salePrice - rentPrice : 0;
    const gapPriceStr = gapPrice > 0 ? `${gapPrice.toFixed(1)}억` : null;

    return (
      <div className="bg-surface/80 dark:bg-zinc-900/80 backdrop-blur-md p-3.5 rounded-[20px] shadow-[0_12px_40px_rgba(0,0,0,0.06)] border border-border/40 dark:border-white/10 flex flex-col gap-2 min-w-[170px] transition-all duration-300 ease-out">
        <div className="text-[12px] font-extrabold text-tertiary mb-0.5">
          {label}
        </div>
        {payload
          .filter((entry) => entry.value !== undefined && entry.value !== null && entry.value > 0)
          .map((entry, index: number) => {
            const isRent =
              entry.dataKey === "동탄 아파트 전세 평균" ||
              entry.name === "평균 전세가";
            return (
              <div
                key={index}
                className="flex items-center justify-between gap-6"
              >
                <div className="flex items-center gap-2">
                  <div
                    className="w-2.5 h-2.5 rounded-full"
                    style={{ backgroundColor: entry.color }}
                  />
                  <span className="text-[13px] font-bold text-secondary">
                    {isRent ? "전세가" : "매매가"}
                  </span>
                </div>
                <span className="text-[13.5px] font-black text-primary">
                  {entry.value}억
                </span>
              </div>
            );
          })}
        {ratio > 0 && (
          <>
            <div className="w-full h-[1px] bg-body my-1" />
            <div className="flex flex-col gap-1.5">
              {gapPriceStr && (
                <div className="flex items-center justify-between gap-4">
                  <span className="text-[12px] font-bold text-tertiary">
                    예상 갭차이
                  </span>
                  <span className="text-[13.5px] font-black text-[#057e77] dark:text-emerald-400">
                    {gapPriceStr}
                  </span>
                </div>
              )}
              <div className="flex items-center justify-between gap-4">
                <span className="text-[12px] font-bold text-tertiary">
                  전세가율
                </span>
                <span className="text-[13.5px] font-black text-[var(--brand-blue)]">
                  {ratio.toFixed(1)}%
                </span>
              </div>
            </div>
          </>
        )}
      </div>
    );
  }
  return null;
};

export interface DiamondVertexProps {
  cx?: number;
  cy?: number;
  radius?: number | string;
  r?: number | string;
  fill?: string;
  stroke?: string;
  strokeWidth?: number | string;
  className?: string;
  payload?: unknown;
  value?: unknown;
  index?: number;
}

/**
 * Diamond vertex component rendering SVG polygon.
 * Points formula: `${cx},${cy - r} ${cx + r},${cy} ${cx},${cy + r} ${cx - r},${cy}`
 * - Standard radius: r = 3.6
 * - Active/Hover radius: r = 6.0
 */
export const DiamondVertex = React.memo(function DiamondVertex({
  cx,
  cy,
  radius = 3.6,
  r,
  fill = "#057e77",
  stroke = "#ffffff",
  strokeWidth = 1.5,
  className,
}: DiamondVertexProps) {
  if (
    typeof cx !== "number" ||
    typeof cy !== "number" ||
    !Number.isFinite(cx) ||
    !Number.isFinite(cy)
  ) {
    return null;
  }

  const effectiveRadius = Number(radius !== undefined ? radius : (r !== undefined ? r : 3.6));
  const points = `${cx},${cy - effectiveRadius} ${cx + effectiveRadius},${cy} ${cx},${cy + effectiveRadius} ${cx - effectiveRadius},${cy}`;

  return (
    <polygon
      points={points}
      fill={fill}
      stroke={stroke}
      strokeWidth={strokeWidth}
      className={className}
    />
  );
});

DiamondVertex.displayName = "DiamondVertex";

export interface MacroTrendChartProps {
  lineData: Array<{
    name: string;
    "동탄 아파트 전체"?: number | null;
    "동탄 아파트 전세 평균"?: number | null;
  }>;
  xTicks: string[];
  yTicks: number[];
  timeframe: string;
  isBottomSheet?: boolean;
  className?: string;
}

// Custom ResizeObserver hook with 150ms debouncing to prevent layout thrashing
function useResizeObserver(delay = 150) {
  const [size, setSize] = useState({ width: 600, height: 330 });
  const sizeRef = useRef({ width: 600, height: 330 });
  const [element, setElement] = useState<HTMLDivElement | null>(null);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const refCallback = React.useCallback((node: HTMLDivElement | null) => {
    if (!node && timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    if (node) {
      const rect = node.getBoundingClientRect();
      const initialW = rect.width > 0 ? rect.width : (node.clientWidth > 0 ? node.clientWidth : 600);
      const initialH = rect.height > 0 ? rect.height : (node.clientHeight > 0 ? node.clientHeight : 330);
      if (initialW > 0 && initialH > 0) {
        sizeRef.current = { width: initialW, height: initialH };
        setSize({ width: initialW, height: initialH });
      }
    }
    setElement(node);
  }, []);

  useEffect(() => {
    if (!element) return;

    function handleResize(entries: ResizeObserverEntry[]) {
      if (typeof document !== 'undefined' && document.body.style.overflow === 'hidden') {
        return;
      }

      if (!entries || !entries.length) return;
      const rawW = entries[0].contentRect.width;
      const rawH = entries[0].contentRect.height;

      if (rawW <= 0 || rawH <= 0) return;

      const width = Math.max(300, Math.floor(rawW));
      const height = Math.max(240, Math.floor(rawH));

      const diffW = Math.abs(width - sizeRef.current.width);
      const diffH = Math.abs(height - sizeRef.current.height);
      if (sizeRef.current.width > 0 && sizeRef.current.height > 0 && diffW <= 2 && diffH <= 2) {
        return;
      }

      if (sizeRef.current.width === 0 || sizeRef.current.height === 0) {
        const newSize = { width, height };
        sizeRef.current = newSize;
        setSize(newSize);
      } else {
        if (timeoutRef.current) {
          clearTimeout(timeoutRef.current);
          timeoutRef.current = null;
        }
        timeoutRef.current = setTimeout(() => {
          const newSize = { width, height };
          sizeRef.current = newSize;
          setSize(newSize);
        }, delay);
      }
    }

    const observer = new ResizeObserver(handleResize);
    observer.observe(element);

    return () => {
      observer.disconnect();
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
        timeoutRef.current = null;
      }
    };
  }, [element, delay]);

  return [refCallback, size] as const;
}

const MacroTrendChart = React.memo(function MacroTrendChart({
  lineData,
  xTicks,
  yTicks,
  timeframe,
  isBottomSheet = false,
  className,
}: MacroTrendChartProps) {
  const [refCallback, size] = useResizeObserver(150);
  const [isTooltipActive, setIsTooltipActive] = useState(false);
  const isTouchDevice = React.useSyncExternalStore(
    (onStoreChange) => {
      if (typeof window === "undefined" || !window.matchMedia) return () => {};
      const mql = window.matchMedia("(pointer: coarse)");
      mql.addEventListener?.("change", onStoreChange);
      return () => mql.removeEventListener?.("change", onStoreChange);
    },
    () => (typeof window !== "undefined" && !!window.matchMedia ? window.matchMedia("(pointer: coarse)").matches : false),
    () => false
  );

  const fontSize = isBottomSheet ? 11 : 12;
  const yWidth = isBottomSheet ? 35 : 40;

  // Process data with null/undefined guards
  const processedData = useMemo(() => {
    return processMacroTrendData(lineData);
  }, [lineData]);

  // Two-sigma statistical confidence interval bounds
  const twoSigmaStats = useMemo<TwoSigmaStats>(() => {
    const saleValues = processedData.map((d) => d["동탄 아파트 전체"]);
    const saleStats = calculateTwoSigma(saleValues);
    if (saleStats.isValid) {
      return saleStats;
    }
    const rentValues = processedData.map((d) => d["동탄 아파트 전세 평균"]);
    const rentStats = calculateTwoSigma(rentValues);
    if (rentStats.isValid) {
      return rentStats;
    }
    return saleStats;
  }, [processedData]);

  const tooltipCursorStyle = useMemo(() => ({
    stroke: "rgba(148, 163, 184, 0.4)",
    strokeWidth: 1.5,
    strokeDasharray: "3 3",
  }), []);

  const nonNullSaleCount = useMemo(() => {
    return processedData.filter(
      (d) => typeof d["동탄 아파트 전체"] === "number" && d["동탄 아파트 전체"]! > 0
    ).length;
  }, [processedData]);

  const nonNullRentCount = useMemo(() => {
    return processedData.filter(
      (d) => typeof d["동탄 아파트 전세 평균"] === "number" && d["동탄 아파트 전세 평균"]! > 0
    ).length;
  }, [processedData]);

  const saleDotProp = useMemo(() => {
    if (nonNullSaleCount === 1) {
      return (dotProps: { cx?: number; cy?: number }) => (
        <DiamondVertex
          cx={dotProps.cx}
          cy={dotProps.cy}
          radius={3.6}
          fill="#057e77"
          stroke="#ffffff"
          strokeWidth={1.5}
        />
      );
    }
    if (isBottomSheet || timeframe === "ALL" || timeframe === "5Y") return false;
    return (dotProps: { cx?: number; cy?: number }) => (
      <DiamondVertex
        cx={dotProps.cx}
        cy={dotProps.cy}
        radius={3.6}
        fill="#057e77"
        stroke="#ffffff"
        strokeWidth={1.5}
      />
    );
  }, [isBottomSheet, timeframe, nonNullSaleCount]);

  const saleActiveDotProp = useMemo(() => {
    return (dotProps: { cx?: number; cy?: number }) => (
      <DiamondVertex
        cx={dotProps.cx}
        cy={dotProps.cy}
        radius={6.0}
        fill="#057e77"
        stroke="#ffffff"
        strokeWidth={2}
      />
    );
  }, []);

  const rentDotProp = useMemo(() => {
    if (nonNullRentCount === 1) {
      return (dotProps: { cx?: number; cy?: number }) => (
        <DiamondVertex
          cx={dotProps.cx}
          cy={dotProps.cy}
          radius={3.6}
          fill="#f9a825"
          stroke="#ffffff"
          strokeWidth={1.5}
        />
      );
    }
    if (isBottomSheet || timeframe === "ALL" || timeframe === "5Y") return false;
    return (dotProps: { cx?: number; cy?: number }) => (
      <DiamondVertex
        cx={dotProps.cx}
        cy={dotProps.cy}
        radius={3.6}
        fill="#f9a825"
        stroke="#ffffff"
        strokeWidth={1.5}
      />
    );
  }, [isBottomSheet, timeframe, nonNullRentCount]);

  const rentActiveDotProp = useMemo(() => {
    return (dotProps: { cx?: number; cy?: number }) => (
      <DiamondVertex
        cx={dotProps.cx}
        cy={dotProps.cy}
        radius={6.0}
        fill="#f9a825"
        stroke="#ffffff"
        strokeWidth={2}
      />
    );
  }, []);

  const desktopEventHandlers = (isTouchDevice && !isBottomSheet)
    ? {
        onTouchStart: () => setIsTooltipActive(true),
        onTouchMove: (e: unknown) => {
          const chartEvent = e as { activePayload?: unknown[] } | null;
          if (chartEvent && chartEvent.activePayload) {
            setIsTooltipActive(true);
          }
        },
        onTouchEnd: () => setIsTooltipActive(false),
      }
    : {};

  const chartW = size.width > 0 ? size.width : 380;
  const chartH = isBottomSheet ? 220 : (size.height > 0 ? size.height : 300);

  return (
    <ChartErrorBoundary fallbackText="동탄 매크로 트렌드 차트를 로드할 수 없습니다.">
      <div
        ref={refCallback}
        data-testid="macro-trend-chart-container"
        className={`w-full h-full flex-1 ${isBottomSheet ? 'min-h-[220px]' : 'min-h-[330px]'} touch-pan-y relative overflow-hidden flex items-center justify-center ${className || ''}`}
      >
      <AreaChart
        width={chartW}
        height={chartH}
        data={processedData}
        margin={{ top: 14, right: 18, left: 4, bottom: 6 }}
        {...desktopEventHandlers}
      >
        <defs>
          <linearGradient id="colorSale" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#057e77" stopOpacity={0.30} />
            <stop offset="95%" stopColor="#057e77" stopOpacity={0.0} />
          </linearGradient>
          <linearGradient id="colorRent" x1="0" y1="0" x2="0" y2="1">
            <stop offset="5%" stopColor="#f9a825" stopOpacity={0.25} />
            <stop offset="95%" stopColor="#f9a825" stopOpacity={0.0} />
          </linearGradient>
        </defs>
        <CartesianGrid
          strokeWidth={0.7}
          vertical={false}
          horizontal={true}
          stroke="rgba(148, 163, 184, 0.18)"
          strokeDasharray="3 3"
        />
        <XAxis
          dataKey="name"
          axisLine={false}
          tickLine={false}
          tick={{ fill: "#64748b", fontSize, fontFamily: "inherit", fontWeight: 700 }}
          dy={10}
          ticks={xTicks}
          tickFormatter={formatXAxisTick}
        />
        <YAxis
          axisLine={false}
          tickLine={false}
          tick={{ fill: "#64748b", fontSize, fontFamily: "inherit", fontWeight: 700 }}
          tickFormatter={(value: number) =>
            value === 0 ? "0" : `${Number.isInteger(value) ? value : value.toFixed(1)}억`
          }
          domain={[0, yTicks && yTicks.length > 0 ? yTicks[yTicks.length - 1] : "auto"]}
          ticks={yTicks}
          width={yWidth}
        />
        <RechartsTooltip
          active={(!isBottomSheet && isTouchDevice) ? isTooltipActive : undefined}
          content={<CustomTooltip />}
          cursor={tooltipCursorStyle}
          isAnimationActive={false}
        />
        {twoSigmaStats.isValid && twoSigmaStats.lower2SD !== null && twoSigmaStats.upper2SD !== null && (
          <SafeReferenceArea
            y1={twoSigmaStats.lower2SD}
            y2={twoSigmaStats.upper2SD}
            fill="var(--brand-primary)"
            fillOpacity={0.06}
            isFront={false}
          />
        )}
        {twoSigmaStats.isValid && twoSigmaStats.upper2SD !== null && (
          <ReferenceLine
            y={twoSigmaStats.upper2SD}
            stroke="var(--brand-primary)"
            strokeDasharray="3 3"
          />
        )}
        {twoSigmaStats.isValid && twoSigmaStats.mean !== null && (
          <ReferenceLine
            y={twoSigmaStats.mean}
            stroke="var(--brand-primary)"
            strokeDasharray="5 5"
          />
        )}
        {twoSigmaStats.isValid && twoSigmaStats.lower2SD !== null && (
          <ReferenceLine
            y={twoSigmaStats.lower2SD}
            stroke="var(--brand-primary)"
            strokeDasharray="3 3"
          />
        )}
        <Area
          key="동탄 아파트 전체"
          type="linear"
          name="평균 매매가"
          dataKey="동탄 아파트 전체"
          stroke="#057e77"
          strokeWidth={isBottomSheet ? 1.8 : 2.2}
          fill="url(#colorSale)"
          isAnimationActive={false}
          connectNulls={true}
          dot={saleDotProp}
          activeDot={saleActiveDotProp}
        />
        <Area
          key="동탄 아파트 전세 평균"
          type="linear"
          name="평균 전세가"
          dataKey="동탄 아파트 전세 평균"
          stroke="#f9a825"
          strokeWidth={isBottomSheet ? 1.2 : 1.5}
          fill="url(#colorRent)"
          isAnimationActive={false}
          connectNulls={true}
          dot={rentDotProp}
          activeDot={rentActiveDotProp}
        />
      </AreaChart>
    </div>
  </ChartErrorBoundary>
  );
});

MacroTrendChart.displayName = 'MacroTrendChart';

export default MacroTrendChart;

